const RC = CONFIG.bike.rider;
const TAU = Math.PI * 2;
const A_REF = (50 / 3.6) / CONFIG.bike.perf.t50;   // m/s² — gia tốc khi vặn hết ga dưới 50 km/h (motion.ts A0)

/* ===== Bảng góc khớp tư thế ngồi nền (rad), thứ tự cố định ===== */
