25	export interface BkInput { gas: number; brake: number; steer: number; hard: boolean; grip: number }   // gas, brake 0..1; steer −1..1 (trái +); hard: phanh gấp; grip 0 (ướt hẳn)..1 (khô)
26	export interface BkState extends DrState { lean: number; leanV: number; susF: number; susFV: number; susR: number; susRV: number; rpm: number; throttle: number; brakeK: number; acc: number; sig: -1 | 0 | 1; sigYaw: number; sigT: number; stuck: number }   // lean: rad (trái +), leanV: rad/s; susF / susR: m lún giảm xóc (+ = nén), susFV / susRV: m/s; rpm: vòng/phút; throttle, brakeK: 0..1 đã làm mượt; acc: m/s² gia tốc dọc; sig: xi nhan −1 phải / 0 / 1 trái; sigYaw: rad đã rẽ theo hướng xi nhan; sigT: s đi thẳng kể từ lúc bật / lần rẽ cuối; stuck: s bị chặn mà vẫn vặn ga
