37	/* ===== Đường cong tăng tốc ===== */
38	let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
39	function bkAccelK(v: number, k: number): number {
40	  if (v <= V50) return A0;
41	  if (v >= P.vMax) return 0;
42	  const u = (v - V50) / (P.vMax - V50);
43	  return A0 * V50 / v * (1 - Math.pow(u, k));
44	}
45	/* Thời gian 0 → 80 km/h với số mũ k (tích phân dv / a, điểm giữa) */
46	function bkT80(k: number): number {
47	  const N = 2000, h = (V80 - V50) / N;
48	  let t = V50 / A0;
49	  for (let i = 0; i < N; i++) t += h / bkAccelK(V50 + (i + 0.5) * h, k);
50	  return t;
51	}
52	function bkFitAccel(): void {
53	  A0 = V50 / P.t50;
54	  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: bkT80 giảm theo k
55	  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (bkT80(m) > P.t80) lo = m; else hi = m; }
56	  KEXP = (lo + hi) / 2;
57	}
58	/* m/s² khi vặn hết ga ở tốc độ v ≥ 0 */
59	export function bkAccel(v: number): number {
60	  if (Number.isNaN(KEXP)) bkFitAccel();
61	  return bkAccelK(v, KEXP);
62	}
