64	/* rad — độ nghiêng lớn nhất ở tốc độ v với độ bám grip: khô ↔ ướt, kẹp để bán kính rẽ không nhỏ hơn turnRadius */
65	export function bkLeanMax(v: number, grip: number): number {
66	  const g = grip > 1 ? 1 : grip < 0 ? 0 : grip, m = P.leanMaxWet + (P.leanMax - P.leanMaxWet) * g;
67	  const geom = Math.atan(v * v / (G * P.turnRadius));
68	  return geom < m ? geom : m;
69	}
