105	/* Về tim làn bên phải của ô mặt đường gần nhất (khoảng cách mặt bằng + chênh cao độ), đứng yên, thẳng đứng.
106	   Chiều đi theo hậu tố id ô (roadData.ts: .S đi Đông, .N đi Tây, .W đi Nam, .E đi Bắc; đi bên phải); ô không có hậu tố (nút giao)
107	   thì dọc cạnh dài, chiều gần hướng xe nhất. Tim làn bên phải = tim ô lệch về bên phải một phần tư bề rộng ô. Không có ô nào thì false */
108	export function bkRecover(s: BkState, net: DrNet): boolean {
109	  const pads = net.pads;
110	  let best = -1, bestD = Infinity;
111	  for (let i = 0; i < pads.length; i++) {
112	    const p = pads[i];
113	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
114	    const cx = s.x < p.x0 ? p.x0 : s.x > p.x1 ? p.x1 : s.x, cz = s.z < p.z0 ? p.z0 : s.z > p.z1 ? p.z1 : s.z;
115	    const d = Math.hypot(cx - s.x, cz - s.z) + Math.abs(p.y(cx, cz) - s.y);
116	    if (d < bestD) { bestD = d; best = i; }
117	  }
118	  if (best < 0) return false;
119	  const p = pads[best], tag = p.id.slice(p.id.lastIndexOf('.') + 1);
120	  let yaw: number;
121	  if (tag === 'S') yaw = 0; else if (tag === 'N') yaw = Math.PI; else if (tag === 'W') yaw = -Math.PI / 2; else if (tag === 'E') yaw = Math.PI / 2;
122	  else if (p.x1 - p.x0 >= p.z1 - p.z0) yaw = Math.cos(s.yaw) >= 0 ? 0 : Math.PI;
123	  else yaw = Math.sin(s.yaw) >= 0 ? Math.PI / 2 : -Math.PI / 2;
124	  const alongX = Math.abs(Math.cos(yaw)) > 0.5, hl = BK_BODY.hl;
125	  const rx = Math.sin(yaw), rz = Math.cos(yaw);                     // vectơ sang phải
126	  const mx = (p.x0 + p.x1) / 2, mz = (p.z0 + p.z1) / 2;
127	  const clampIn = (a: number, a0: number, a1: number) => a1 - a0 <= 2 * hl ? (a0 + a1) / 2 : a < a0 + hl ? a0 + hl : a > a1 - hl ? a1 - hl : a;
128	  s.x = alongX ? clampIn(s.x, p.x0, p.x1) : mx + rx * (p.x1 - p.x0) / 4;
129	  s.z = alongX ? mz + rz * (p.z1 - p.z0) / 4 : clampIn(s.z, p.z0, p.z1);
130	  s.y = p.y(s.x, s.z); s.yaw = yaw;
131	  s.v = 0; s.steer = 0; s.lean = 0; s.leanV = 0; s.throttle = 0; s.brakeK = 0; s.acc = 0; s.braking = false;
132	  s.slide = 1; s.touch = 0; s.stuck = 0;
133	  bkPitch(s, net);
134	  return true;
135	}
136	
137	const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
138	
139	/* Một bước h ≤ sim.dt */
140	function bkStep1(s: BkState, inp: BkInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
141	  const gas = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, bIn = inp.hard ? 1 : inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
142	  const grip = inp.grip > 1 ? 1 : inp.grip < 0 ? 0 : inp.grip === inp.grip ? inp.grip : 1;   // NaN ⇒ khô
143	  /* ga, phanh làm mượt; trung bình trong bước */
144	  const t0 = s.throttle, b0 = s.brakeK;
145	  s.throttle = gas + (t0 - gas) * Math.exp(-h / P.throttleTau);
146	  s.brakeK = bIn + (b0 - bIn) * Math.exp(-h / P.brakeTau);
147	  const thr = (t0 + s.throttle) / 2, bk = (b0 + s.brakeK) / 2;
148	  const rate = inp.hard ? P.hardBrakeWet + (P.hardBrake - P.hardBrakeWet) * grip : P.brakeWet + (P.brake - P.brakeWet) * grip;
149	  /* tốc độ */
150	  const v0 = s.v;
151	  let v = v0;
152	  if (v < 0 || (v <= SIM.revV && bIn > 0 && gas === 0)) {
153	    if (bIn > 0 && gas === 0) {
154	      if (v > 0) v = Math.max(0, v - bk * rate * h);                  // phanh nốt rồi mới dắt lùi
155	      else { const tgt = -P.walkBack * bk; v = v > tgt ? Math.max(tgt, v - P.walkBack * h) : Math.min(tgt, v + P.walkBack * h); }
156	    } else v = bkToward0(v, (P.coast + thr * P.walkBack) * h);        // nhả / vặn ga khi đang dắt lùi: về 0
157	  } else {
158	    const a = thr * bkAccel(v) - bk * rate - (v > 0 ? (1 - thr) * P.coast : 0);   // hãm nhả ga chỉ khi đang chạy: đứng yên vặn ga thì nhích ngay
159	    v = v + a * h;
160	    v = v < 0 ? 0 : v > P.vMax ? P.vMax : v;
161	  }
162	  s.acc = (v - v0) / h;
163	  const vm = (v0 + v) / 2, av = vm > 0 ? vm : 0, w = av < P.vBlend ? av / P.vBlend : 1;
164	  /* ghi đông (lái động học khi chậm) */
165	  const want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer === inp.steer ? inp.steer : 0;   // NaN ⇒ thẳng
166	  let st = s.steer;
167	  if (want === 0) st = bkToward0(st, P.steerReturn * STEER_MAX * h);
168	  else {
169	    const tgt = want * STEER_MAX, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
170	    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_MAX * h;
171	    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
172	  }
173	  const kKin = Math.tan(st) / L;
174	  /* độ nghiêng: lò xo giảm chấn tới hạn, nghiệm đúng trên bước h với đích giữ nguyên */
175	  const tgtLean = w * want * bkLeanMax(av, grip) + (1 - w) * Math.atan(av * av * kKin / G);
176	  const om = 2 * Math.PI * (P.leanHz + (P.leanHzFast - P.leanHz) * Math.min(1, av / P.vMax));
177	  const l0 = s.lean, A = l0 - tgtLean, Bc = s.leanV + om * A, e = Math.exp(-om * h);
178	  let lean = tgtLean + (A + Bc * h) * e, leanV = (Bc - om * (A + Bc * h)) * e;
179	  if (lean > P.leanMax) { lean = P.leanMax; leanV = 0; } else if (lean < -P.leanMax) { lean = -P.leanMax; leanV = 0; }
180	  /* độ cong: trộn độ cong từ độ nghiêng (kẹp ≤ 1 / turnRadius) với độ cong động học; xoay = độ cong × quãng */
181	  const tl = Math.tan((l0 + lean) / 2);
182	  let kLean = av > 1e-6 ? G * tl / (av * av) : 0;
183	  if (kLean > KAPPA_MAX) kLean = KAPPA_MAX; else if (kLean < -KAPPA_MAX) kLean = -KAPPA_MAX;
184	  const kappa = vm >= 0 ? w * kLean + (1 - w) * kKin : kKin;        // dắt lùi: chỉ động học
185	  /* dời thân xe */
186	  const dist = vm * h, f = drMove(net, s, dist, dist * kappa, boxes, nBoxes, MOVED);
187	  const dyaw = MOVED.yaw - s.yaw;
188	  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
189	  /* va chạm: như drStep1 của ô tô */
190	  let slide = s.slide ?? 1, touch = s.touch ?? 0;
191	  if (f < 1) {
192	    if (touch > 0) v = bkToward0(v, P.scrape * h);
193	    const q = f > 0 ? Math.sqrt(f) : 0;
194	    if (q === 0) v = 0;
195	    else if (q < slide) v *= q / slide;
196	    if (q < slide) slide = q;
197	    touch = SIM.touch;
198	  } else if (touch > 0) { touch -= h; if (touch <= 0) { touch = 0; slide = 1; } }
199	  s.slide = slide; s.touch = touch;
200	  s.v = v; s.steer = st; s.lean = lean; s.leanV = leanV; s.braking = bIn > 0;
201	  s.wheel += dist * f / (B.wheelDia / 2);
202	  /* bị chặn mà vẫn vặn ga */
203	  s.stuck = gas > 0 && touch > 0 && Math.abs(v) < 1 ? s.stuck + h : 0;
204	  /* độ dốc, giảm xóc */
205	  const p0 = s.pitch;
206	  bkPitch(s, net);
207	  const kick = SUS.bumpK * (s.pitch - p0) * Math.abs(vm), n = SUS.noise * Math.min(1, Math.abs(v) / P.vMax);
208	  const den = 1 + 2 * SUS.damp * SUS_W * h + SUS_W * SUS_W * h * h;
209	  const tF = -s.acc * SUS.diveK + (NOISE() * 2 - 1) * n, tR = s.acc * SUS.diveK + (NOISE() * 2 - 1) * n;
210	  s.susFV = (s.susFV + kick + h * SUS_W * SUS_W * (tF - s.susF)) / den; s.susF += h * s.susFV;
211	  s.susRV = (s.susRV + kick + h * SUS_W * SUS_W * (tR - s.susR)) / den; s.susR += h * s.susRV;
212	  if (s.susF > SUS.travel) { s.susF = SUS.travel; s.susFV = 0; } else if (s.susF < -SUS.travel) { s.susF = -SUS.travel; s.susFV = 0; }
213	  if (s.susR > SUS.travel) { s.susR = SUS.travel; s.susRV = 0; } else if (s.susR < -SUS.travel) { s.susR = -SUS.travel; s.susRV = 0; }
214	  /* vòng tua */
215	  const rt = bkRpm(v, s.throttle);
216	  s.rpm = rt + (s.rpm - rt) * Math.exp(-h / (rt > s.rpm ? CVT.tauUp : CVT.tauDown));
217	  /* xi nhan */
218	  if (s.sig !== 0) {
219	    s.sigYaw += dyaw * s.sig;
220	    if (s.sigYaw >= SG.cancelYaw && want * s.sig <= 0) { s.sig = 0; s.sigYaw = 0; s.sigT = 0; }
221	    else if (dyaw * s.sig > 0.05 * h) s.sigT = 0;                   // đang rẽ theo hướng xi nhan (> 0,05 rad/s)
222	    else if ((s.sigT += h) > SG.cancelS) { s.sig = 0; s.sigYaw = 0; s.sigT = 0; }
223	  }
224	}
