226	/* Bước mô phỏng cho khung dài dt (s). Đang / cần sơ tán khỏi nhịp quay thì khung dành cho sơ tán (đầu vào bỏ qua), xe thẳng đứng */
227	export function bkStep(s: BkState, inp: BkInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
228	  if (drEvacStep(s, net, dt)) { s.lean = 0; s.leanV = 0; s.throttle = 0; s.brakeK = 0; s.acc = 0; s.stuck = 0; return; }
229	  let rem = dt;
230	  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
231	    const h = rem < SIM.dt ? rem : SIM.dt;
232	    bkStep1(s, inp, net, boxes, nBoxes, h);
233	    rem -= h;
234	  }
235	}
