290	/* Tấm bóng mờ: như drShadowShared của ô tô (mép mềm hình vuông bo), cùng tham số vật liệu ⇒ cùng program */
291	function bkShadowShared(): void {
292	  if (shadowMat) return;
293	  const n = 32, d = new Uint8Array(n * n * 4);
294	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
295	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
296	    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;
297	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
298	  }
299	  const tex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); tex.needsUpdate = true;
300	  tex.magFilter = tex.minFilter = THREE.LinearFilter;
301	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: tex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
302	  shadowMat.name = 'bikeShadow';
303	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
304	}
