316	/* ===== Vật liệu đèn: phát sáng × max(uNight · night, uOn); `night` nằm trong chuỗi shader nên khóa program theo `key` ===== */
317	function bkLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, on: number): void {
318	  const uOn = { value: on };
319	  m.onBeforeCompile = (s) => {
320	    s.uniforms.uNight = shared.uNight;
321	    s.uniforms.uOn = uOn;
322	    s.fragmentShader = 'uniform float uNight;\nuniform float uOn;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
323	      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uOn );`);
324	  };
325	  m.customProgramCacheKey = () => key;
326	  m.userData.lampOn = on;
327	}
