336	/* Chuẩn hóa cảnh đã nạp thành nguồn dùng chung. Thiếu nút / vật liệu / trục thì ném lỗi (bkModelLoad bắt, trả null) */
337	export function bkModelSource(scene: THREE.Object3D): BkSource {
338	  for (const n of ['body', 'front', 'wheel_f', 'wheel_r', ...ANCHORS.map((a) => a[1])]) if (!scene.getObjectByName(n)) throw new Error(`thiếu nút ${n}`);
339	  const a = scene.getObjectByName('front')!.userData.axis as number[] | undefined;
340	  if (!Array.isArray(a) || a.length !== 3) throw new Error('front thiếu userData.axis');
341	  const axis = new THREE.Vector3(a[0], a[1], a[2]).normalize();
342	  const mats = new Map<string, THREE.MeshStandardMaterial>();
343	  scene.traverse((o) => {
344	    o.layers.set(1);
345	    const me = o as THREE.Mesh;
346	    if (!me.isMesh) return;
347	    me.castShadow = false; me.receiveShadow = false;
348	    const mat = me.material as THREE.MeshStandardMaterial;
349	    if (!mats.has(mat.name)) mats.set(mat.name, mat);
350	  });
351	  for (const n of ['lamp_head', 'lamp_tail', 'lamp_sig_l', 'lamp_sig_r', 'dash']) if (!mats.has(n)) throw new Error(`thiếu vật liệu ${n}`);
352	  bkLampPatch(mats.get('lamp_head')!, 'bkLampHead', M.headNight, M.headDay);
353	  const tail = mats.get('lamp_tail')!; bkLampPatch(tail, 'bkLampTail', M.tailNight, 0);
354	  const tailBrake = tail.clone(); bkLampPatch(tailBrake, 'bkLampTail', M.tailNight, M.tailBrake);   // cùng khóa: chỉ khác uniform
355	  const sig = (m: THREE.MeshStandardMaterial): THREE.MeshStandardMaterial => { bkLampPatch(m, 'bkLampSig', 0, 0); const on = m.clone(); bkLampPatch(on, 'bkLampSig', 0, M.sigOn); return on; };
356	  const sigL = mats.get('lamp_sig_l')!, sigR = mats.get('lamp_sig_r')!;
