401	    .then((s) => { if (s !== LATE) return s; console.warn(`Lái xe máy: nạp mô hình xe quá ${M.timeoutMs} ms, dùng hình tạm`); return null; },
402	      (e) => { console.warn('Lái xe máy: không nạp được mô hình xe, dùng hình tạm', e); return null; })
403	    .finally(() => clearTimeout(timer));
404	  late = work.catch(() => null);   // lỗi đã báo ở nhánh race
405	  cache = p;
406	  return p;
407	}
