412	}
413	
414	/* ===== Một xe máy ===== */
415	export class BkBike {
416	  readonly group = new THREE.Group();
417	  private readonly roll = new THREE.Group();                         // nút cuộn lean quanh đường chạm đất
418	  anchors: BkAnchors;
419	  dashMat: THREE.MeshBasicMaterial | null = null;
420	  private temp: THREE.Mesh | null;
421	  private tempGeo: THREE.BufferGeometry | null;
422	  private disposed = false;
423	  private src: BkSource | null = null;
424	  private root: THREE.Object3D | null = null;                        // bản sao `scooter`: phần trên lò xo
425	  private front: THREE.Object3D | null = null;
426	  private wheelF: THREE.Object3D | null = null;
427	  private wheelR: THREE.Object3D | null = null;
428	  private readonly frontQ0 = new THREE.Quaternion(); private readonly wfQ0 = new THREE.Quaternion(); private readonly wrQ0 = new THREE.Quaternion();
429	  private readonly frontP0 = new THREE.Vector3(); private readonly wfP0 = new THREE.Vector3(); private readonly wrP0 = new THREE.Vector3();
430	  private readonly axisF = new THREE.Vector3();                      // trục cổ lái trong hệ cục bộ của front lúc nghỉ
431	  private tailMeshes: THREE.Mesh[] = []; private sigLMeshes: THREE.Mesh[] = []; private sigRMeshes: THREE.Mesh[] = [];
432	  private brakingNow = false; private sigLNow = false; private sigRNow = false;
433	  private readonly last: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
434	  private placed = false;
435	
436	  constructor() {
437	    this.group.name = 'bike';
438	    this.group.add(this.roll);
439	    this.tempGeo = bkTempGeometry();
440	    this.temp = new THREE.Mesh(this.tempGeo, bkTempMaterial());
441	    this.temp.name = 'bike-temp';
442	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
443	    this.roll.add(this.temp);
444	    bkShadowShared();
445	    const sh = new THREE.Mesh(shadowGeo!, shadowMat!);
446	    sh.scale.set(B.length + 2 * M.shadow.pad, 1, B.width + 2 * M.shadow.pad);
447	    sh.position.y = M.shadow.lift;
448	    sh.layers.set(1); sh.castShadow = false; sh.receiveShadow = false; sh.renderOrder = 1;
449	    this.group.add(sh);
450	    const a = {} as BkAnchors;
451	    for (const [k, n] of ANCHORS) { const o = new THREE.Object3D(); o.name = 'bike-temp-' + n; this.roll.add(o); a[k] = o; }
452	    this.anchors = a;
453	    void bkModelLoad();
454	    late!.then((src) => { if (src && !this.disposed) this.swap(src); });   // không bao giờ từ chối
455	  }
456	
457	  /* Có mô hình thật chưa */
458	  get real(): boolean { return this.root !== null; }
459	
460	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
461	  private swap(src: BkSource): void {
462	    if (this.root || this.disposed) return;
463	    const root = src.scene.clone();
464	    this.src = src;
465	    this.front = root.getObjectByName('front')!; this.wheelF = root.getObjectByName('wheel_f')!; this.wheelR = root.getObjectByName('wheel_r')!;
466	    this.frontQ0.copy(this.front.quaternion); this.frontP0.copy(this.front.position);
467	    this.wfQ0.copy(this.wheelF.quaternion); this.wfP0.copy(this.wheelF.position);
468	    this.wrQ0.copy(this.wheelR.quaternion); this.wrP0.copy(this.wheelR.position);
469	    this.axisF.copy(src.axis).applyQuaternion(_q.copy(this.frontQ0).invert());
470	    this.dashMat = bkDashMaterial();
471	    root.traverse((o) => {
472	      const m = o as THREE.Mesh;
473	      if (!m.isMesh) return;
474	      const mat = m.material as THREE.Material;
475	      if (mat.name === 'dash') m.material = this.dashMat!;
476	      else if (mat === src.tail) this.tailMeshes.push(m);
477	      else if (mat === src.sigL) this.sigLMeshes.push(m);
478	      else if (mat === src.sigR) this.sigRMeshes.push(m);
479	    });
480	    for (const [k] of ANCHORS) this.anchors[k].removeFromParent();
481	    const a = {} as BkAnchors;
482	    for (const [k, n] of ANCHORS) a[k] = root.getObjectByName(n)!;
483	    this.anchors = a;
484	    this.root = root;
485	    this.roll.add(root);
486	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
487	    this.brakingNow = false; this.sigLNow = false; this.sigRNow = false;
488	    if (this.placed) this.place(this.last);
489	  }
490	
491	  place(p: BkPlace): void {
492	    const l = this.last;
493	    if (p !== l) { l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.lean = p.lean; l.steer = p.steer; l.wheel = p.wheel; l.susF = p.susF; l.susR = p.susR; l.braking = p.braking; l.sig = p.sig; }
494	    this.placed = true;
495	    const g = this.group;
496	    g.position.set(p.x, p.y, p.z);
497	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(_q.setFromAxisAngle(AXZ, p.pitch));
498	    this.roll.rotation.x = -p.lean;                                  // lean > 0 nghiêng trái (−Z cục bộ)
499	    const root = this.root;
500	    if (!root) return;
501	    const front = this.front!, wf = this.wheelF!, wr = this.wheelR!;
502	    /* cổ lái: xoay quanh trục (kẹp góc khóa lái); bánh trước trượt dọc trục theo susF */
503	    const st = p.steer > M.steerLock ? M.steerLock : p.steer < -M.steerLock ? -M.steerLock : p.steer === p.steer ? p.steer : 0;
504	    front.quaternion.setFromAxisAngle(this.src!.axis, st).multiply(this.frontQ0);
505	    wf.position.copy(this.axisF).multiplyScalar(p.susF).add(this.wfP0);
506	    wr.position.set(this.wrP0.x, this.wrP0.y + p.susR, this.wrP0.z);
507	    /* bánh lăn quanh Z cục bộ: xe tiến thì góc âm */
508	    wf.quaternion.copy(this.wfQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
509	    wr.quaternion.copy(this.wrQ0).multiply(_q.setFromAxisAngle(AXZ, -p.wheel));
510	    /* phần trên lò xo: xoay φ quanh Z, dời ty sao cho hai tâm bánh về độ cao nghỉ của bánh sau (bánh chạm đất) */
511	    _v.copy(wf.position).applyQuaternion(front.quaternion).add(this.frontP0);   // tâm bánh trước trong hệ root
512	    const xf = _v.x, yf = _v.y, xr = wr.position.x, yr = wr.position.y;
513	    const phi = Math.atan2(yr - yf, xf - xr), sn = Math.sin(phi), cs = Math.cos(phi);
514	    root.rotation.set(0, 0, phi);
515	    root.position.set(0, this.wrP0.y - (xr * sn + yr * cs), 0);
516	    /* đèn: phanh, xi nhan (nửa chu kỳ đầu sáng) */
517	    if (p.braking !== this.brakingNow) {
518	      this.brakingNow = p.braking;
519	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
520	      for (const m of this.tailMeshes) m.material = mat;
521	    }
522	    const ph = shared.uTime.value * M.sigHz, blink = ph - Math.floor(ph) < 0.5;
523	    const onL = p.sig === 1 && blink, onR = p.sig === -1 && blink;
524	    if (onL !== this.sigLNow) { this.sigLNow = onL; const mat = onL ? this.src!.sigLOn : this.src!.sigL; for (const m of this.sigLMeshes) m.material = mat; }
525	    if (onR !== this.sigRNow) { this.sigRNow = onR; const mat = onR ? this.src!.sigROn : this.src!.sigR; for (const m of this.sigRMeshes) m.material = mat; }
526	  }
527	
528	  dispose(): void {
529	    if (this.disposed) return;
530	    this.disposed = true;
531	    this.group.removeFromParent();
532	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; }
533	    this.tempGeo?.dispose(); this.tempGeo = null;
534	    this.dashMat?.dispose(); this.dashMat = null;
535	    if (this.root) { this.roll.remove(this.root); this.root = null; }
536	    this.tailMeshes.length = 0; this.sigLMeshes.length = 0; this.sigRMeshes.length = 0;
537	  }
538	}
