  bkCamDrag(c, 0, 1e6); assert.equal(c.pitch, C1.pitchMin);
  bkCamDrag(c, 0, -1e6); assert.equal(c.pitch, C1.pitchMax);
  bkCamDrag(c, 300, 0);
  const y0 = c.yaw;
  assert.ok(y0 < 0, 'kéo sang phải ⇒ nhìn sang phải (yaw giảm)');
