// Kiểm tay người lái xe máy (Task 4): chụp ảnh các góc. Không commit (tests/screens/ bị bỏ qua).
import { launch, openApp, frames } from '../lib.mjs';
const URL = process.env.URL || 'http://localhost:5199/?explore=bike';
const only = process.argv.slice(2);
const browser = await launch();
const { page, errors } = await openApp(browser, URL, { width: 900, height: 600, before: async (p) => p.addInitScript((c) => localStorage.setItem('stChar', c), process.env.CH || '0') });
page.on('console', (m) => { if (m.type() === 'warning' || m.type() === 'error') console.log('[console]', m.type(), m.text().slice(0, 200)); });
await page.waitForFunction(() => window.__app.bike.state && window.__app.bike.model && window.__app.bike.model.real && window.__app.bike.rider, null, { polling: 1000, timeout: 400000 });
console.log('đã có xe thật + người lái');
const info = await page.evaluate(() => { const s = window.__app.bike.state; return { x: s.x, y: s.y, z: s.z, yaw: s.yaw }; });
console.log('xe ở', JSON.stringify(info));

async function shot(name, { steer = 0, lean = 0, night = 0, view, fp = false }) {
  const res = await page.evaluate(({ steer, lean, night, view, fp, info }) => {
    const A = window.__app, b = A.bike;
    A.dayNight.night = night; A.dayNight.target = night;
    A.cam.mode = 'bike';
    b.placeAt(info.x, info.z, info.yaw);
    const s = b.state; s.steer = steer; s.lean = lean;
    b.rider.setFirstPerson(fp);
    for (let i = 0; i < 40; i++) b.step(1 / 60, { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 }), s.steer = steer, s.lean = lean, s.v = 0;
    b.model.place(s);
    b.step(0, { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 });
    A.cam.mode = 'car';   // khóa camera: không chế độ nào đặt camera
    const c = A.camera, f = [Math.cos(s.yaw), 0, -Math.sin(s.yaw)], r = [Math.sin(s.yaw), 0, Math.cos(s.yaw)];
    const P = (a, bb, u) => [s.x + f[0] * a + r[0] * bb, s.y + u, s.z + f[2] * a + r[2] * bb];
    const [p, t] = view(P);
    c.near = 0.05; c.fov = 40; c.updateProjectionMatrix();
    c.position.set(...p); c.lookAt(...t);
    return b.rider.debug();
  }, { steer, lean, night, view: undefined, fp, info }).catch((e) => String(e));
  return res;
}
// view được truyền dạng chuỗi hàm vì evaluate không nhận hàm lồng
const views = {
  side: 'P => [P(0.1, -2.8, 1.0), P(0.1, 0, 0.85)]',
  sideR: 'P => [P(0.1, 2.8, 1.0), P(0.1, 0, 0.85)]',
  front: 'P => [P(3.0, 0.2, 1.3), P(0, 0, 0.9)]',
  rear: 'P => [P(-2.2, 1.7, 1.7), P(0, 0, 0.9)]',
  turn: 'P => [P(2.0, -0.6, 2.4), P(-0.1, 0, 0.9)]',
  hands: 'P => [P(0.3, -1.0, 1.7), P(-0.1, 0, 1.05)]',
  top: 'P => [P(-0.15, 0.0, 3.6), P(-0.15, 0.001, 0.6)]',
  fp: 'P => [P(-0.47, 0, 1.53), P(3, 0, 0.9)]'
};
const plan = [
  ['side', { view: 'side' }], ['sideR', { view: 'sideR' }], ['front', { view: 'front' }], ['rear', { view: 'rear' }],
  ['turn', { view: 'turn', steer: 0.52 }], ['turnR', { view: 'turn', steer: -0.52 }], ['hands', { view: 'hands' }], ['top', { view: 'top' }],
  ['lean', { view: 'rear', lean: 0.5 }], ['night', { view: 'side', night: 1 }], ['night-front', { view: 'front', night: 1 }], ['fp', { view: 'fp', fp: true }]
];
for (const [name, o] of plan) {
  if (only.length && !only.includes(name)) continue;
  const res = await page.evaluate(({ o, v, info }) => {
    const A = window.__app, b = A.bike, view = eval(v);
    A.dayNight.night = o.night || 0; A.dayNight.target = o.night || 0;
    A.cam.mode = 'bike';
    b.placeAt(info.x, info.z, info.yaw);
    const s = b.state;
    b.rider.setFirstPerson(!!o.fp);
    for (let i = 0; i < 40; i++) { s.steer = o.steer || 0; s.lean = o.lean || 0; s.v = 0; b.step(1 / 60, { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 }); }
    s.steer = o.steer || 0; s.lean = o.lean || 0;
    b.step(0, { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 });
    A.cam.mode = 'car';
    const c = A.camera, f = [Math.cos(s.yaw), 0, -Math.sin(s.yaw)], r = [Math.sin(s.yaw), 0, Math.cos(s.yaw)];
    const P = (a, bb, u) => [s.x + f[0] * a + r[0] * bb, s.y + u, s.z + f[2] * a + r[2] * bb];
    const [p, t] = view(P);
    c.near = 0.05; c.fov = 40; c.updateProjectionMatrix();
    c.position.set(...p); c.lookAt(...t);
    return { dbg: b.rider.debug(), steer: s.steer, lean: s.lean };
  }, { o, v: views[o.view], info });
  await frames(page, o.night ? 6 : 3);
  await page.screenshot({ path: `tests/screens/bike-rider-${name}${process.env.CH === '1' ? '-f' : ''}.png` });
  console.log(name, JSON.stringify(res));
}
const dc = await page.evaluate(() => { const g = window.__app.bike.rider.group; let n = 0; g.traverse((o) => { if (o.isMesh) n += Array.isArray(o.material) ? o.material.length : 1; }); return n; });
console.log('số lệnh vẽ người lái (lưới × vật liệu):', dc);
const eye = await page.evaluate(() => { const b = window.__app.bike, T = window.__app.THREE; const seat = b.model.anchors.seat, eyeA = b.model.anchors.eye; b.rider.setFirstPerson(false); b.model.group.updateMatrixWorld(true);
  const inv = seat.matrixWorld.clone().invert(); const L = b.rider.group.getObjectByName('Bip01_LEye'), R = b.rider.group.getObjectByName('Bip01_REye');
  const p = (o) => new T.Vector3().setFromMatrixPosition(o.matrixWorld).applyMatrix4(inv).toArray().map((v) => +v.toFixed(3));
  return { eyeAnchor: p(eyeA), riderEyeL: p(L), riderEyeR: p(R) }; }).catch((e) => String(e));
console.log('mắt (hệ yên):', JSON.stringify(eye));

