// Kiểm tay góc nhìn thứ nhất xe máy (Task 5). Không commit (tests/screens/ bị bỏ qua).
import { launch, openApp, frames } from '../lib.mjs';
const URL = process.env.URL || 'http://localhost:5199/?explore=bike';
const only = process.argv.slice(2);
const browser = await launch();
const { page, errors } = await openApp(browser, URL, { width: 960, height: 540, before: async (p) => p.addInitScript((c) => localStorage.setItem('stChar', c), process.env.CH || '0') });
page.on('console', (m) => { if (m.type() === 'warning' || m.type() === 'error') console.log('[console]', m.type(), m.text().slice(0, 200)); });
await page.waitForFunction(() => window.__app.bike.state && window.__app.bike.model && window.__app.bike.model.real && window.__app.bike.rider, null, { polling: 1000, timeout: 400000 });
const start = await page.evaluate(() => { const s = window.__app.bike.state; return { x: s.x, y: s.y, z: s.z, yaw: s.yaw }; });
console.log('xe ở', JSON.stringify(start));
/* chỗ: tìm ô mặt đường theo loại */
const spots = await page.evaluate(() => {
  const n = window.__app.bike.net, out = {};
  for (const p of n.pads) {
    const w = p.x1 - p.x0, h = p.z1 - p.z0;
    if (p.kind === 'tunnel' && !out.tunnel && /\.S$|\.N$|\.E$|\.W$/.test(p.id)) out.tunnel = { id: p.id, x0: p.x0, x1: p.x1, z0: p.z0, z1: p.z1 };
    if (p.kind === 'road' && !out.street && Math.abs(p.x0) > 400 && Math.max(w, h) > 150) out.street = { id: p.id, x0: p.x0, x1: p.x1, z0: p.z0, z1: p.z1 };
  }
  out.kinds = [...new Set(n.pads.map((p) => p.kind))];
  return out;
});
console.log('chỗ', JSON.stringify(spots));

const IN = (gas, steer) => ({ gas, brake: 0, steer, hard: false, grip: 1 });
async function run(name, o) {
  if (only.length && !only.includes(name)) return;
  const res = await page.evaluate(({ o, start }) => {
    const A = window.__app, b = A.bike;
    A.dayNight.night = o.night || 0; A.dayNight.target = o.night || 0;
    const p = o.at || start;
    b.placeAt(p.x, p.z, p.yaw ?? start.yaw);
    b.setView(o.view || 1);
    const s = b.state;
    /* tăng tốc tới v rồi giữ, lái steer */
    for (let i = 0; i < 400 && s.v < (o.v ?? 11); i++) b.step(1 / 30, { gas: 1, brake: 0, steer: 0, hard: false, grip: 1 });
    for (let i = 0; i < (o.hold ?? 60); i++) b.step(1 / 30, { gas: s.v < (o.v ?? 11) ? 1 : 0, brake: 0, steer: o.steer || 0, hard: false, grip: 1 });
    const c = A.camera;
    return { v: +(s.v * 3.6).toFixed(1), lean: +s.lean.toFixed(3), roll: +b.cam.roll.toFixed(3), mix: b.cam.mix, fov: c.fov, near: c.near, camY: +(c.position.y - s.y).toFixed(3), y: s.y, x: +s.x.toFixed(1), z: +s.z.toFixed(1) };
  }, { o, start });
  /* giữ trạng thái: đóng băng chuyển động giữa hai ảnh (xe đứng yên ở v hiện tại không được, nên chặn update) */
  await page.evaluate(() => { const b = window.__app.bike; b._upd = b.update; b.update = () => {}; });
  await frames(page, o.night ? 8 : 4);
  await page.screenshot({ path: `tests/screens/bike-fp-${name}.png` });
  if (o.twice) { await frames(page, 2); await page.screenshot({ path: `tests/screens/bike-fp-${name}-2.png` }); }
  await page.evaluate(() => { const b = window.__app.bike; b.update = b._upd; });
  console.log(name, JSON.stringify(res));
}
await run('day', { v: 11, hold: 20, twice: true });
await run('lean', { v: 11, steer: 1, hold: 25 });
await run('night', { v: 11, hold: 20, night: 1 });
await run('bridge', { v: 8, hold: 10 });
if (spots.street) { const p = spots.street, al = p.x1 - p.x0 > p.z1 - p.z0; await run('street', { at: { x: al ? p.x0 + 30 : (p.x0 + p.x1) / 2 + 3, z: al ? (p.z0 + p.z1) / 2 + 3 : p.z1 - 30, yaw: al ? 0 : Math.PI / 2 }, v: 11, hold: 10 }); }
if (spots.tunnel) { const p = spots.tunnel, al = p.x1 - p.x0 > p.z1 - p.z0; await run('tunnel', { at: { x: al ? p.x0 + 20 : (p.x0 + p.x1) / 2 + 2, z: al ? (p.z0 + p.z1) / 2 : p.z1 - 20, yaw: al ? 0 : Math.PI / 2 }, v: 8, hold: 10 }); }
await run('third', { v: 11, hold: 30, view: 3 });
console.log('lỗi', errors.slice(0, 5));
await browser.close();

